css:
.mz *,.mz *::before,.mz *::after{box-sizing: border-box; margin: 0; padding: 0;}
.mz .recuerda{border: 2px solid var(--bosque); border-radius: 10px; padding: 8px 12px; margin-bottom: 11px;}
.mz .recuerda-titulo{font-size: 13px; font-weight: 700; font-family: sans-serif; margin-bottom: 5px;}
.mz .recuerda-ejemplos{display: flex; flex-wrap: wrap; gap: 8px 26px; align-items: flex-start;}
.mz .rec-ej{font-size: 14px; line-height: 1.45;}
.mz .rec-ej b{font-size: 18px;}
.mz .cdu-tabla{border-collapse: collapse; margin-bottom: 4px;}
.mz .cdu-tabla th,.mz .cdu-tabla td{border: 1.5px solid var(--bosque); text-align: center;}
.mz .cdu-tabla th{font-family: sans-serif; font-size: 12px; background: #f3f3f3; padding: 3px 0; width: 60px;}
.mz .cdu-tabla .num-cab{width: 80px; background: #fff; font-size: 19px; font-weight: 700; font-family: 'PW-ficha', cursive;}
.mz .cdu-tabla td{height: 34px; font-size: 19px; font-weight: 700;}
.mz .construir-fila{display: flex; align-items: center; gap: 8px; font-size: 17px; font-weight: 700; margin-bottom: 7px; flex-wrap: wrap;}
.mz .construir-fila .pieza{border: 1.5px solid var(--bosque); border-radius: 6px; padding: 4px 9px;}
.mz .construir-fila .igual{font-size: 19px;}
.mz .construir-fila .caja-res{width: 90px; height: 38px; border: 1.5px solid var(--bosque); border-radius: 6px;}
.mz .suma-fila{display: flex; align-items: center; gap: 8px; font-size: 18px; font-weight: 700; margin-bottom: 8px; flex-wrap: wrap;}
.mz .suma-fila .num-grande{min-width: 70px;}
.mz .suma-fila .caja-sum{width: 78px; height: 36px; border: 1.5px solid var(--bosque); border-radius: 6px;}
.mz .suma-fila .mas{font-family: sans-serif;}
.mz .serie-cajas{display: flex; gap: 6px; flex-wrap: wrap; font-size: 16px; font-weight: 700;}
.mz .serie-cajas .caja-num{width: 54px; height: 40px; border: 1.5px solid var(--bosque); border-radius: 6px; display: flex; align-items: center; justify-content: center;}
.mz .serie-cajas .caja-num.vacia{background: #fff;}
.mz .rec-ej{line-height: 1.725 !important;}
